"""Coordinator write-ahead transaction log."""

from dataclasses import dataclass
from typing import Dict, List


@dataclass
class LogRecord:
    tx_id: str
    state: str
    participants: List[str]


class CoordinatorWAL:
    def __init__(self):
        self.records: Dict[str, LogRecord] = {}

    def write(self, tx_id: str, state: str, participants: List[str]) -> None:
        self.records[tx_id] = LogRecord(tx_id, state, list(participants))

