"""Coordinator crash recovery engine."""

from typing import Dict, List
from coordinator_log import CoordinatorWAL
from participant import ParticipantRM
from tx_state import TxState


class TwoPhaseRecoveryEngine:
    def __init__(self, wal: CoordinatorWAL, participants: Dict[str, ParticipantRM]):
        self.wal = wal
        self.participants = participants

    def recover_all_transactions(self) -> Dict[str, str]:
        results: Dict[str, str] = {}
        for tx_id, record in self.wal.records.items():
            if record.state in (TxState.COMMITTED, TxState.PREPARED):
                # If PREPARED was logged, all participants voted YES before crash; commit forward
                for p_id in record.participants:
                    self.participants[p_id].commit(tx_id)
                self.wal.write(tx_id, TxState.COMMITTED, record.participants)
                results[tx_id] = TxState.COMMITTED
            elif record.state in (TxState.INIT, TxState.ABORTED):
                for p_id in record.participants:
                    self.participants[p_id].abort(tx_id)
                results[tx_id] = TxState.ABORTED
        return results
